/* ---------- Payment form ---------- */
.pyx{padding:16px;display:flex;flex-direction:column;gap:12px;max-width:360px;margin:0 auto;width:100%}
.pyx-h{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}
.pyx-h>div:first-child{display:flex;flex-direction:column;font-size:14px}
.pyx-h b{font-weight:500}
.pyx-h .muted{font-size:12px}
.pyx-per button{font-size:12px;height:26px;padding:0 9px}
.pyx-f{display:flex;flex-direction:column;gap:5px;font-size:12.5px;font-weight:500;min-width:0}
.pyx-in{display:flex;align-items:center;height:40px;border-radius:11px;background:var(--chip);box-shadow:inset 0 0 0 1px var(--field-line);padding:0 10px 0 12px;transition:box-shadow .25s,background .25s}
.pyx-in:focus-within{background:var(--surface);box-shadow:inset 0 0 0 2px var(--focus),0 0 0 4px var(--accent-bg)}
.pyx-f.bad .pyx-in{box-shadow:inset 0 0 0 1.5px var(--bad)}
/* a field marked wrong still shows the focus ring while it has the focus; the message says what is wrong */
.pyx-f.bad .pyx-in:focus-within{box-shadow:inset 0 0 0 2px var(--focus),0 0 0 4px var(--accent-bg)}
.pyx-in input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-family:var(--mono);font-size:13.5px;font-weight:400;color:var(--fg);letter-spacing:.02em}
.pyx-in input::placeholder{color:var(--muted)}
.pyx-br{font-size:10px;font-weight:500;letter-spacing:.04em;padding:3px 6px;border-radius:5px;opacity:0;transform:scale(.8);transition:opacity .3s,transform .35s var(--ease)}
.pyx-br.on{opacity:1;transform:none}
.pyx-2{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.pyx-sum{display:flex;flex-direction:column;gap:6px;padding:12px;border-radius:12px;background:var(--chip);font-size:12.5px;color:var(--fg2)}
.pyx-sum>div{display:flex;justify-content:space-between}
.pyx-dc{color:var(--ok);transition:opacity .3s}
.pyx-dc.off{opacity:.3;text-decoration:line-through}
.pyx-t{padding-top:6px;border-top:1px solid var(--line);color:var(--fg);font-size:13.5px}
.pyx-t b{font-weight:500}
.pyx-go{height:42px;width:100%}
.pyx-go.ok{background:var(--ok)}
.pyx-n{font-size:11.5px;text-align:center}

DM.def('payment-form', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{lock}', I('lock','xs'));
  const cn = $('.pyx-cn', r), ex = $('.pyx-ex', r), cv = $('.pyx-cv', r), br = $('.pyx-br', r);
  const BR = [[/^4/, 'VISA', '#1a1f71'], [/^5[1-5]/, 'MC', '#eb001b'], [/^3[47]/, 'AMEX', '#2e77bb']];
  cn.oninput = demo => { const d = cn.value.replace(/\D/g, '').slice(0, 16); cn.value = d.replace(/(.{4})/g, '$1 ').trim(); const b = BR.find(x => x[0].test(d));
    br.classList.toggle('on', !!b); if (b){ br.textContent = b[1]; br.style.background = b[2]; br.style.color = '#fff'; } cn.closest('.pyx-f').classList.remove('bad'); if (d.length === 16 && demo !== true) ex.focus({ preventScroll:true }); };
  ex.oninput = () => { let d = ex.value.replace(/\D/g, '').slice(0, 4); if (d.length === 1 && +d > 1) d = '0' + d; ex.value = d.length > 2 ? d.slice(0, 2) + ' / ' + d.slice(2) : d; ex.closest('.pyx-f').classList.remove('bad'); if (d.length === 4) cv.focus({ preventScroll:true }); };
  cv.oninput = () => { cv.value = cv.value.replace(/\D/g, ''); cv.closest('.pyx-f').classList.remove('bad'); };
  let per = 'y', tot = 691.2;
  function price(){ const unit = 24, sub = unit * 3, yr = per === 'y'; const t = yr ? sub * 12 * .8 : sub;
    $('.pyx-s', r).textContent = '$' + (yr ? sub * 12 : sub).toFixed(2); $('.pyx-d', r).textContent = yr ? '−$' + (sub * 12 * .2).toFixed(2) : '−$0.00'; $('.pyx-dc', r).classList.toggle('off', !yr);
    $('.pyx-u', r).textContent = yr ? '$24 × 12' : '$24';
    tween(tot, t, 600, v => { tot = v; $('.pyx-tot', r).textContent = '$' + v.toFixed(2); $('.pyx-gt', r).textContent = '$' + v.toFixed(2); }); }
  seg($('.pyx-per', r), v => { per = v; price(); });
  price();
  $('.pyx', r).onsubmit = e => { e.preventDefault(); let ok = true;
    [[cn, cn.value.replace(/\D/g, '').length === 16], [ex, /^\d\d \/ \d\d$/.test(ex.value)], [cv, cv.value.length >= 3]].forEach(([el, good]) => { if (!good){ ok = false; const f = el.closest('.pyx-f'); f.classList.remove('bad'); void f.offsetWidth; f.classList.add('bad'); } });
    if (!ok) return;
    c.run(async () => { const go = $('.pyx-go', r); go.innerHTML = '<span class="spin" style="border-color:rgba(255,255,255,.3);border-top-color:#fff"></span>Processing'; await c.wait(1200); go.classList.add('ok'); go.innerHTML = I('check','xs') + 'Payment successful'; enter(go.firstChild); }); };
  // the preview types a test card on its own; clicking, focusing or typing in it takes over, and what it had typed goes
  c.auto(1000, () => c.run(() => c.type(cn, '4242424242424242', { ms:45, each:() => cn.oninput(true) })));
});
